const RET={
en:['Search the Monitor','Search','Close','Results','No results','Community contributions','Read full context','Live social tools','Open the existing live Bluesky and on-demand platform tools. No embeds load here.','Unable to load this source. Try again.','Sources'],
pt:['Buscar no Monitor','Buscar','Fechar','Resultados','Nenhum resultado','Contribuições da comunidade','Ler contexto completo','Ferramentas sociais ao vivo','Abrir as ferramentas existentes do Bluesky e das plataformas sob demanda. Nada é incorporado aqui.','Não foi possível carregar esta fonte. Tente novamente.','Fontes'],
es:['Buscar en el Monitor','Buscar','Cerrar','Resultados','Sin resultados','Aportes de la comunidad','Leer el contexto completo','Herramientas sociales en vivo','Abrir las herramientas existentes de Bluesky y plataformas bajo demanda. No se cargan contenidos incrustados aquí.','No se pudo cargar esta fuente. Inténtelo de nuevo.','Fuentes'],
fr:['Rechercher dans le Monitor','Rechercher','Fermer','Résultats','Aucun résultat','Contributions de la communauté','Lire le contexte complet','Outils sociaux en direct','Ouvrir les outils existants Bluesky et les plateformes à la demande. Aucun contenu intégré ici.','Impossible de charger cette source. Réessayez.','Sources'],
ru:['Поиск в Monitor','Поиск','Закрыть','Результаты','Нет результатов','Материалы сообщества','Прочитать полный контекст','Социальные инструменты онлайн','Открыть существующие инструменты Bluesky и платформы по запросу. Встраиваемый контент здесь не загружается.','Не удалось загрузить источник. Попробуйте снова.','Источники'],
zh:['搜索 Monitor','搜索','关闭','结果','没有结果','社区贡献','阅读完整背景','实时社交工具','打开现有 Bluesky 和按需平台工具。此处不会加载嵌入内容。','无法加载此来源。请重试。','来源'],
ar:['البحث في المرصد','بحث','إغلاق','النتائج','لا توجد نتائج','مساهمات المجتمع','قراءة السياق الكامل','أدوات التواصل المباشرة','فتح أدوات Bluesky الحالية والمنصات عند الطلب. لا يُحمّل محتوى مضمّن هنا.','تعذر تحميل المصدر. حاول مرة أخرى.','المصادر']};
const rt=i=>RET[lang][i];
function classicURL(hash){const u=new URL(window.COP31_CLASSIC||'https://cop31.grupotrie.com.br/',location.href);u.search='?lang='+lang;u.hash=hash;return u.href}
function approvedEntry(en){return !!(en&&en.status==='published'&&en.approved_by&&en.approved_at&&en.sources?.some(s=>s?.verified===true))}
let publicCommunity=null,searchGeneration=0,searchMatches=[],searchLimit=100;
function showSearchMatches(){const panel=$('site-search-results'),shown=searchMatches.slice(0,searchLimit);panel.innerHTML=`<h2>${esc(rt(3))}: ${shown.length} / ${searchMatches.length}</h2>`+(shown.length?shown.map(x=>`<p dir="auto"><a href="${x.url.startsWith('#')?esc(x.url):safeURL(x.url)}">${esc(x.title)}</a></p>`).join(''):esc(rt(4)))+(shown.length<searchMatches.length?`<button type="button" id="site-search-more">${esc(t(12))}</button>`:'');if($('site-search-more'))$('site-search-more').onclick=()=>{const nextIndex=searchLimit;searchLimit+=100;showSearchMatches();$('site-search-results').querySelectorAll('a')[nextIndex]?.focus()};}

function communityRows(){const box=$('community');if(!box||!publicCommunity)return;const rows=publicCommunity.entries.filter(approvedEntry);box.hidden=!rows.length;box.innerHTML=`<h2>${esc(rt(5))}</h2>`+rows.map(en=>{const fields=['headline','summary','what_happened','what_changed','why_it_matters','watch_next','open_questions'],tr=en.i18n?.[lang],complete=tr&&fields.every(k=>!en[k]||tr[k]),v=k=>(complete?tr[k]:en[k])||'';return `<article class="post" lang="${complete?lang:'pt-BR'}"><h3 dir="auto">${esc(v('headline'))}</h3><p dir="auto">${esc(v('summary'))}</p><p>${esc(en.classification||'')} · ${esc(en.verification||'')}</p>${(en.corrections||[]).map(c=>`<p dir="auto"><bdi>${esc(date(c.at))}</bdi> · ${esc(c.i18n?.[lang]||c.note)}</p>`).join('')}<a href="${esc(classicURL(en.article&&/^[a-z0-9-]{3,80}$/.test(en.article)?'hoje/leitura/'+en.article:'hoje'))}">${esc(rt(6))}</a></article>`}).join('')}
async function loadCommunity(){if(!window.COP31_DATA?.today)return;try{const r=await fetch(dataURL('today'));if(!r.ok)throw Error('today');const d=await r.json();if(!Array.isArray(d.entries))throw Error('today');publicCommunity=d;communityRows()}catch{$('community').hidden=false;$('community').textContent=rt(9)}}
function retentionLabels(){if(!$('site-search'))return;searchGeneration++;$('site-search-results').hidden=true;$('site-search-label').textContent=rt(0);$('site-search-submit').textContent=rt(1);$('site-search-close').textContent=rt(2);$('social-tools').innerHTML=`<h2><a href="${esc(classicURL('pulso'))}">${esc(rt(7))}</a></h2><p>${esc(rt(8))}</p>`;communityRows()}
async function siteSearch(){const query=slug($('site-search-input').value.trim()),token=++searchGeneration;const panel=$('site-search-results');panel.hidden=false;if(query.length<2){panel.textContent=rt(4);return}panel.textContent='…';try{
const key=lang;await loadPulse();if(!explores[key]){const r=await fetch('explore-'+key+'.json');if(!r.ok)throw Error('references');explores[key]=await r.json()}if(!positions){const r=await fetch('positions.json');if(!r.ok)throw Error('positions');positions=await r.json()}if(token!==searchGeneration)return;
const results=[];for(const row of positions)results.push({title:row.slice(0,3).join(' · '),text:row.join(' '),url:'#posicoes'});for(const d of activeDocuments())results.push({title:d.title,text:d.title+' '+d.symbol,url:d.url});
for(const f of feed.items)results.push({title:sourceTitle(f)||f.text||f.summary,text:[sourceTitle(f),description(f),f.text,f.institution,...(f.tracks||[])].join(' '),url:f.url});
for(const [section,html] of Object.entries(explores[key].sections)){const node=document.createElement('div');node.innerHTML=html;results.push({title:node.querySelector('h2,h3')?.textContent||section,text:node.textContent,url:'#'+section})}
for(const en of publicCommunity?.entries.filter(approvedEntry)||[])results.push({title:en.i18n?.[key]?.headline||en.headline,text:JSON.stringify([en.headline,en.summary,en.i18n?.[key]]),url:classicURL('hoje')});
searchMatches=results.filter(x=>slug(x.text).includes(query));searchLimit=100;showSearchMatches();
}catch{if(token===searchGeneration)panel.textContent=rt(9)}}
const searchBox=document.createElement('section');searchBox.className='site-search';searchBox.innerHTML='<form id="site-search"><label for="site-search-input" id="site-search-label"></label><div class="search-actions"><input id="site-search-input" type="search" minlength="2" required><button id="site-search-submit"></button><button type="button" id="site-search-close"></button></div></form><div id="site-search-results" role="status" hidden></div>';$('main').prepend(searchBox);
const community=document.createElement('section');community.id='community';community.hidden=true;$('today').appendChild(community);
const social=document.createElement('aside');social.id='social-tools';$('pulse').prepend(social);
$('site-search').addEventListener('submit',e=>{e.preventDefault();siteSearch()});$('site-search-close').onclick=()=>{searchGeneration++;$('site-search-results').hidden=true;$('site-search-input').value=''};
const beforeRetentionRender=render;render=function(){beforeRetentionRender();retentionLabels()};
const beforeRetentionRoute=route;route=function(){const h=location.hash.slice(1);if(/^hoje\/leitura\/[a-z0-9-]{3,80}$/.test(h)||h==='newsletter'){location.assign(classicURL(h));return}beforeRetentionRoute()};window.addEventListener('hashchange',route);retentionLabels();loadCommunity();
